"""Génère les pages du site EDGC237 à partir de products.json.
Usage : python3 build.py DOSSIER_SITE   (le dossier contient style.css, fonts/, logo.jpg...)
Pour changer un prix ou un produit : modifier products.json, relancer, puis zipper le dossier à plat."""
import json,sys,os,html,urllib.parse as U
D=json.load(open(os.path.join(os.path.dirname(os.path.abspath(__file__)),"products.json"),encoding="utf-8"))
OUT=sys.argv[1] if len(sys.argv)>1 else "."
SITE=D["site"];P=D["products"]
def wa(t): return "https://wa.me/237675444463?text="+U.quote(t)
def fmt(n): return f"{n:,}".replace(","," ")
ICON={"home":"M3 11l9-8 9 8v9a1 1 0 01-1 1h-5v-6H9v6H4a1 1 0 01-1-1z","eleves":"M5 4h14v16H7a2 2 0 01-2-2V4zM9 8h6M9 12h6","ens":"M3 4h18v12H3zM8 20l4-4 4 4","etab":"M4 21V7l8-4 8 4v14zM9 21v-6h6v6","buy":"M5 8h14l-1 13H6zM9 8a3 3 0 016 0"}
NAV=[("index","/","Accueil","home"),("eleves","/eleves","Élèves","eleves"),("enseignants","/enseignants","Enseignants","ens"),("etablissements","/etablissements","Écoles","etab"),("acheter","/acheter","Acheter","buy")]
TRACK='document.addEventListener("click",function(e){var a=e.target.closest("a[data-p]");if(a&&window.gtag)gtag("event","buy_click",{item_name:a.dataset.p,value:+a.dataset.v||0,currency:"XAF",channel:a.dataset.c})})'
def page(slug,title,desc,body,hero="",ld=""):
    nav="".join(f'<a href="{h}"'+(' aria-current="page"' if s==slug else "")+f'><svg viewBox="0 0 24 24" aria-hidden="true"><path d="{ICON[i]}"/></svg>{l}</a>' for s,h,l,i in NAV)
    url=SITE+("/" if slug=="index" else "/"+slug)
    out=f'''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>{title}</title><meta name="description" content="{desc}"><meta name="theme-color" content="#0A5C0A"><link rel="canonical" href="{url}"><meta property="og:type" content="website"><meta property="og:title" content="{title}"><meta property="og:description" content="{desc}"><meta property="og:url" content="{url}"><meta property="og:image" content="{SITE}/og-image.jpg"><link rel="icon" href="/favicon.ico"><link rel="icon" type="image/png" sizes="32x32" href="/favicon-32.png"><link rel="preload" href="/fonts/bg-800.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="/style.css">{ld}<script async src="https://www.googletagmanager.com/gtag/js?id=G-9BWRWQ6PNS"></script><script>window.dataLayer=window.dataLayer||[];function gtag(){{dataLayer.push(arguments)}}gtag("js",new Date());gtag("config","G-9BWRWQ6PNS");{TRACK}</script></head><body><header><div class="wrap"><a href="/"><img src="/logo.jpg" width="40" height="40" alt=""><b>EDGC237</b></a></div></header><main>{hero}<div class="wrap">{body}</div></main><footer><div class="wrap"><p><b>École Digitale de Géographie du Cameroun</b></p><p>Téléphone et WhatsApp : <a href="tel:+237675444463">675444463</a> / <a href="tel:+237693132834">693132834</a></p><p>Site : <a href="{SITE}">{SITE}</a></p><p><a href="/cgu">Conditions de vente</a> · <a href="/confidentialite">Confidentialité</a></p></div></footer><nav class="tabs" aria-label="Rubriques">{nav}</nav></body></html>'''
    open(os.path.join(OUT,slug+".html"),"w",encoding="utf-8").write(out)
def row(pid,page):
    p=P[pid];b=p["buy"];kind,_,v=b.partition(":")
    if kind=="chariow": href=D["chariow"]+v+"?utm_source=edgc237&utm_medium=site&utm_campaign=vitrine";ch="chariow"
    elif kind=="wa": href=wa(v);ch="whatsapp"
    else: href=v;ch="interne"
    price=p.get("price_text") or fmt(p["price"]);unit=p.get("unit","FCFA")
    inc=f'<p>{p["inc"]}</p>' if p.get("inc") else ""
    ap=f'<a class="apercu" href="{p["apercu"]}">Aperçu gratuit</a>' if p.get("apercu") else ""
    cls=" ".join(x for x in (p.get("cls",""),"star" if p.get("star") else "") if x)
    rid=pid if page!="etablissements" else pid+"-ecoles"
    return f'<article class="row {cls}" id="{rid}"><div class="tag">{p["tag"]}</div><h3>{p["name"]}</h3>{inc}{ap}<div class="foot"><div class="price">{price} <small>{unit}</small></div><a class="btn" href="{html.escape(href)}" data-p="{html.escape(p["name"])}" data-v="{p.get("price",0)}" data-c="{ch}">{p.get("label","Acheter")}</a></div></article>'
def groups(page):
    o=""
    for g in D["groups"][page]:
        h,sub,ids=g[0],g[1],g[2];i=f' id="{g[3]}"' if len(g)>3 else ""
        o+=f'<h2{i}>{h}</h2>'+(f'<p class="sub">{sub}</p>' if sub else "")+'<div class="rows">'+"".join(row(x,page) for x in ids)+"</div>"
    return o
def lead(h,l): return f'<div class="pg"><h1>{h}</h1><p class="lead">{l}</p></div>'
def chan(t,u,label): return f'<div class="chan"><h3>{t}</h3><p>Conseils et ressources gratuits, chaque semaine.</p><a class="btn g" href="{u}">{label}</a></div>'
hero='<section class="hero"><div class="wrap"><h1>Les supports qui font réussir, de la 6ème en Terminale.</h1><p>Kits, fascicules et guides pédagogiques conformes aux arrêtés MINESEC. Paiement Mobile Money, PDF livré aussitôt.</p><div class="btns"><a class="btn" href="/eleves">Voir les supports élèves</a><a class="btn alt" href="/enseignants">Espace enseignants</a></div></div></section>'
body='<div class="doors"><a class="door" href="/eleves"><h3>Élèves</h3><p>Kits par classe dès 3 500 FCFA et fascicules DÉMASQUER à 1 200 FCFA.</p></a><a class="door" href="/enseignants"><h3>Enseignants et répétiteurs</h3><p>Réseau Pro, packs matière, licence répétiteur, planches A3.</p></a><a class="door" href="/etablissements"><h3>Écoles et établissements</h3><p>Licence multi-utilisateurs pour toutes les classes. Devis sur demande.</p></a></div><h2>L’offre du moment</h2><p class="sub">Tout le secondaire en une seule commande.</p><div class="rows">'+row(D["home_offer"],"index")+'</div><h2>Comment commander</h2><ol class="steps"><li><b>Choisis ton support</b>Kit, fascicule ou pack.</li><li><b>Paie en Mobile Money</b>MTN MoMo ou Orange Money.</li><li><b>Reçois ton PDF</b>Livraison dès la confirmation du paiement.</li></ol>'+chan("Reste informé gratuitement",D["channels"]["principale"],"Rejoindre la chaîne WhatsApp")
page("index","EDGC237 — Supports, kits et guides pédagogiques","Supports, kits et guides pédagogiques EDGC237 de la 6ème en Terminale, conformes aux arrêtés MINESEC. Paiement Mobile Money, livraison PDF.",body,hero)
items=[{"@type":"Product","name":P[i]["name"],"description":P[i].get("inc") or P[i]["tag"],"brand":{"@type":"Brand","name":"EDGC237"},"offers":{"@type":"Offer","price":str(P[i]["price"]),"priceCurrency":"XAF","availability":"https://schema.org/InStock","url":SITE+"/eleves#"+i}} for g in D["groups"]["eleves"] for i in g[2] if P[i].get("price")]
ld='<script type="application/ld+json">'+json.dumps({"@context":"https://schema.org","@graph":items},ensure_ascii=False)+"</script>"
page("eleves","Supports pour élèves, de la 6ème en Terminale — EDGC237","Kits par classe à 3 500 FCFA et fascicules DÉMASQUER à 1 200 FCFA pour le BEPC, le Probatoire et le BAC. Conformes aux arrêtés MINESEC.",lead("Supports pour les élèves","De la 6ème en Terminale, conformes aux arrêtés MINESEC. Tu paies en Mobile Money, tu reçois ton PDF.")+groups("eleves"),ld=ld)
page("enseignants","Ressources pour enseignants et répétiteurs — EDGC237","Réseau Pro, packs matière, licence répétiteur, fascicules DÉMASQUER et planches A3 pour enseignants d’Histoire, Géographie et ECM.",lead("Enseignants et répétiteurs","Des ressources prêtes à l’emploi pour préparer, évaluer et gagner du temps.")+groups("enseignants")+chan("Chaîne Enseignants et Répétiteurs",D["channels"]["enseignants"],"Rejoindre la chaîne WhatsApp"))
page("etablissements","Licence pour établissements scolaires — EDGC237","Licence multi-utilisateurs EDGC237 pour toutes les classes et matières, de 25 000 à 50 000 FCFA selon la taille de l’établissement.",lead("Écoles et établissements","Équipez toute votre équipe pédagogique avec une seule licence.")+groups("etablissements"))
pay='<div class="pay"><a href="tel:+237675444463">MTN MoMo<span>675444463</span></a><a href="tel:+237693132834">Orange Money<span>693132834</span></a></div>'
body=lead("Comment acheter","Deux façons de commander, sans création de compte.")+'<h2>Achat en ligne</h2><p class="sub">Pour les kits par classe et les fascicules DÉMASQUER.</p><ol class="steps"><li><b>Clique sur « Acheter »</b>À côté du produit choisi.</li><li><b>Paie sur la boutique</b>Le paiement Mobile Money se fait sur la page de la boutique, pas sur nos numéros.</li><li><b>Reçois ton PDF</b>Livraison immédiate, avec ton nom en filigrane.</li></ol><h2>Commande par WhatsApp</h2><p class="sub">Pour le Pack Combo, le Réseau Pro, les licences et les devis.</p><ol class="steps"><li><b>Clique sur « Commander »</b>Le message est déjà écrit : complète-le avec ta classe ou ta matière.</li><li><b>Paie en Mobile Money</b>Sur l’un de ces deux numéros.</li><li><b>Envoie la capture du paiement</b>Tu reçois ton accès ou ton PDF sur WhatsApp.</li></ol>'+pay+'<h2>Un souci avec ta commande ?</h2><p class="sub">PDF perdu ou livraison non reçue : écris-nous en indiquant le numéro utilisé pour le paiement.</p><div class="btns"><a class="btn g" href="'+wa("Bonjour EDGC237, j’ai un souci avec ma commande. Numéro utilisé pour le paiement :")+'">Écrire sur WhatsApp</a><a class="btn g" href="'+D["shop"]+'">Boutique en ligne</a></div>'
page("acheter","Comment acheter — EDGC237","Commandez vos supports EDGC237 : achat en ligne ou commande WhatsApp, paiement MTN MoMo ou Orange Money, réception du PDF.",body)
def legal(s,t,secs):
    b=f'<div class="pg legal"><h1>{t}</h1><p>Dernière mise à jour : octobre 2026</p>'+"".join(f"<h2>{h}</h2><p>{x}</p>" for h,x in secs)+"</div>"
    page(s,t+" — EDGC237",t+" de l’École Digitale de Géographie du Cameroun (EDGC237).",b)
legal("cgu","Conditions de vente",[("1. Éditeur","L’EDGC237 (École Digitale de Géographie du Cameroun) est une plateforme pédagogique camerounaise fondée par Sylvin WANDJA NZOUATCHAM, PhD, Docteur en Géographie. Contact : +237 675 444 463 / +237 693 132 834."),("2. Produits","Les supports vendus sur ce site sont des documents numériques au format PDF. Les prix sont affichés en francs CFA (FCFA). Les contenus sont conformes aux arrêtés MINESEC en vigueur."),("3. Commande et paiement","Les kits et fascicules s’achètent en ligne sur la boutique associée au site. Les autres produits se commandent par WhatsApp et se paient par MTN Mobile Money (675 444 463) ou Orange Money (693 132 834)."),("4. Livraison","Le PDF est livré dès la confirmation du paiement. En cas de problème de livraison, contactez-nous aux numéros ci-dessus."),("5. Remboursement","Les produits numériques étant livrés immédiatement, aucun remboursement n’est accordé, sauf erreur manifeste de livraison."),("6. Propriété intellectuelle","Les contenus de l’EDGC237 sont protégés par le droit d’auteur. Toute reproduction, diffusion ou utilisation commerciale sans autorisation écrite est interdite. Les fascicules achetés en ligne portent un filigrane nominatif ; les autres supports peuvent en porter un."),("7. Responsabilité","L’EDGC237 s’engage sur la qualité et la conformité de ses contenus, mais ne peut être tenue responsable des résultats obtenus aux examens.")])
legal("confidentialite","Politique de confidentialité",[("1. Données collectées","Pour les commandes par WhatsApp : votre numéro de téléphone et les informations du paiement Mobile Money (numéro et montant). Pour les achats en ligne : les informations demandées par la boutique (par exemple nom et adresse e-mail), traitées par son prestataire. Le site mesure aussi sa fréquentation avec Google Analytics, sous forme de statistiques de visite."),("2. Utilisation","Vos données servent uniquement à livrer vos commandes, à répondre à vos demandes et à vous envoyer des contenus pédagogiques si vous les avez demandés."),("3. Partage","Vos données ne sont jamais vendues ni cédées à des tiers."),("4. Conservation et suppression","Les données de commande sont conservées 12 mois après votre dernière commande. Vous pouvez demander leur suppression à tout moment au +237 675 444 463."),("5. Sécurité","L’EDGC237 met en œuvre les mesures raisonnables pour protéger vos données contre tout accès non autorisé."),("6. Contact","Pour toute question : +237 675 444 463 / +237 693 132 834.")])
pg=["","eleves","enseignants","etablissements","acheter","cgu","confidentialite"]
open(os.path.join(OUT,"sitemap.xml"),"w").write('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+"".join(f"<url><loc>{SITE}/{p}</loc></url>" for p in pg)+"</urlset>")
